#include <vector>

int main() {
    std::vector<double> homework = {92.5, 88.0, 79.5};
    std::println("一共 {} 门课", homework.size());

    std::vector<int> zeros(5, 0);
    std::vector<int> nines(3, 9);
    for (int one : nines) {
        std::print("{} ", one);
    }
    std::println("   ← 共 {} 格", nines.size());

    return 0;
}

